// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"gabapentin":{"wirkmechanismus":"Dämpft die übermässige Aktivität von Nervenzellen und lindert so Nervenschmerzen und Krampfanfälle. Gabapentin bindet an die Alpha-2-Delta-Untereinheit spannungsabhängiger Calciumkanäle und vermindert dadurch die Freisetzung erregender Botenstoffe wie Glutamat und Substanz P. Es wird nicht in der Leber verstoffwechselt, sondern unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel","Gang- und Koordinationsstörungen (Ataxie)","Müdigkeit, Fieber","Virusinfektionen"],"haeufig":["Infekte der Atem- und Harnwege, Mittelohrentzündung","Appetitveränderungen, Gewichtszunahme","Feindseligkeit, Verwirrtheit, Stimmungsschwankungen, Depression, Angst, Denkstörungen","Zittern, Sprechstörungen, Gedächtnisverlust, Kribbeln, Augenzittern, Sehstörungen (Doppelbilder)","Übelkeit, Erbrechen, Durchfall, Verstopfung, Mundtrockenheit, Verdauungsbeschwerden","Hautausschlag, Juckreiz, Akne, Gesichtsschwellung","Gelenk-, Muskel- und Rückenschmerzen, Erektionsstörungen","Wassereinlagerungen (periphere Ödeme), Gangstörungen, Stürze"],"gelegentlich":["Allergische Reaktionen (z. B. Nesselsucht)","Hyperglykämie (erhöhter Blutzucker)","Kognitive Störungen, Unruhe","Herzklopfen","Schluckbeschwerden"],"selten":["Bewusstlosigkeit","Hypoglykämie (Unterzuckerung)","Atemdepression (Atemdämpfung)"],"unbekannt":["Thrombozytopenie (Mangel an Blutplättchen)","Multiorgan-Überempfindlichkeitsreaktion (DRESS), Anaphylaxie, Angioödem","Hyponatriämie (Natriummangel)","Halluzinationen, Suizidgedanken, Abhängigkeit","Bewegungsstörungen (Choreoathetose, Myoklonien), Ohrensausen","Pankreatitis, Hepatitis, Gelbsucht","Stevens-Johnson-Syndrom, Erythema multiforme, Haarausfall","Rhabdomyolyse (Muskelzerfall), akutes Nierenversagen, Entzugssymptome"]},"schwangerschaft":"Nur begrenzte Daten; Anwendung nur nach ärztlicher Abwägung, wenn der Nutzen das mögliche Risiko überwiegt. Nicht eigenmächtig absetzen.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, Kind auf Schläfrigkeit beobachten.","hinweise":["Nicht abrupt absetzen, sondern über mindestens eine Woche ausschleichen (Entzugssymptome, Krampfanfälle).","Alkohol meiden; Fahrtüchtigkeit ist besonders zu Beginn eingeschränkt.","Bei Atemproblemen, starker Schläfrigkeit oder Hautausschlag sofort ärztlich melden.","Antazida mit mindestens 2 Stunden Abstand einnehmen."],"darreichung":["Kapseln","Filmtabletten"]},"gadobensaeure":{"wirkmechanismus":"Verstärkt den Kontrast in MRT-Bildern; ein kleiner Teil wird zusätzlich von den Leberzellen aufgenommen, was die Erkennung von Leberherden verbessert. Das paramagnetische Gadolinium verkürzt die T1-Relaxationszeit benachbarter Wasserstoffkerne und hellt das Gewebe im T1-Bild auf; durch eine schwache, vorübergehende Bindung an Albumin ist die Signalverstärkung stärker als bei rein extrazellulären Mitteln. Wenige Prozent der Dosis werden von Leberzellen aufgenommen und über die Galle ausgeschieden; dadurch erscheint gesundes Lebergewebe in der späten Leberphase hell, während Herde ohne funktionierende Leberzellen dunkel bleiben. Der Hauptteil wird unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"unbekannt":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien), Geschmacksstörungen","Übelkeit, Erbrechen, Durchfall, Mundtrockenheit","Hitzegefühl, Hautrötung, Blutdruckanstieg","Juckreiz, Hautausschlag, Nesselsucht","Reaktionen an der Injektionsstelle, Fieber","Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock","Krampfanfälle, Herzrhythmusstörungen, Ohnmacht","Nephrogene systemische Fibrose (Verhärtung von Haut und Bindegewebe) bei schwerer Niereninsuffizienz"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt notwendig ist; Gadolinium kann die Plazenta passieren.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über. Ob das Stillen für 24 Stunden unterbrochen wird, entscheiden Ärztin oder Arzt und Mutter gemeinsam.","hinweise":["Vor der Untersuchung Nierenerkrankungen, Dialyse, Lebertransplantation, Allergien und frühere Kontrastmittelreaktionen angeben.","Nach der Injektion mindestens 30 Minuten unter Beobachtung bleiben.","Bei Nierenkranken: Hautverdickungen, Gelenksteifigkeit oder Schmerzen in den Wochen nach der Untersuchung ärztlich melden."],"darreichung":["Injektionslösung"]},"gadobutrol":{"wirkmechanismus":"Verstärkt im MRT-Bild den Kontrast, sodass Tumoren, Entzündungen und Gefässe deutlicher erkennbar werden. Gadobutrol ist ein nichtionischer Komplex des paramagnetischen Metalls Gadolinium mit einem makrozyklischen Liganden, der das Metall sehr stabil bindet. Es verkürzt die T1-Relaxationszeit der Wasserstoffkerne im Gewebe. Dank der hohen Konzentration (1 mmol/ml) genügt ein kleines Injektionsvolumen; die Ausscheidung erfolgt unverändert über die Nieren.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit"],"gelegentlich":["Schwindel, Geschmacksstörung, Kribbeln (Parästhesie)","Atemnot","Erbrechen","Hautrötung, Juckreiz, Ausschlag","Wärmegefühl, Reaktionen an der Injektionsstelle"],"selten":["Überempfindlichkeitsreaktionen bis zum anaphylaktoiden Schock (Nesselsucht, Schwellungen, Bronchospasmus, Blutdruckabfall)","Bewusstlosigkeit, Krampfanfälle, Geruchsstörung","Herzrasen, Herzklopfen","Mundtrockenheit, Unwohlsein, Kältegefühl"],"unbekannt":["Herzstillstand","Nephrogene systemische Fibrose (Verhärtung von Haut, Gelenken und Organen)","Gadoliniumablagerungen im Gehirn"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt nötig ist.","stillzeit":"Geht nur in sehr geringer Menge in die Muttermilch über. Ob nach der Untersuchung 24 Stunden lang nicht gestillt wird, entscheiden Ärztin oder Arzt und Mutter gemeinsam.","hinweise":["Vor der Untersuchung Nierenerkrankungen, frühere Kontrastmittelreaktionen, Allergien und Epilepsie angeben.","Nach der Injektion mindestens 30 Minuten unter Beobachtung bleiben; verzögerte Reaktionen können noch Tage später auftreten.","Bei Nierenschwäche: Hautverdickung, Schwellungen oder Gelenksteife in den Wochen nach der Untersuchung ärztlich melden."],"darreichung":["Injektionslösung (Durchstechflasche, Fertigspritze)"]},"gadoteridol":{"wirkmechanismus":"Verstärkt den Kontrast in MRT-Bildern, sodass krankhafte Veränderungen besser erkennbar werden. Das paramagnetische Gadolinium verkürzt die Relaxationszeit der umliegenden Wasserstoffkerne, was im T1-gewichteten Bild zu einem helleren Signal führt. Gadoteridol ist ein stabiler makrozyklischer Komplex, der kaum freies Gadolinium abgibt; er verteilt sich im Extrazellulärraum und wird mit einer Halbwertszeit von etwa 1,6 Stunden unverändert über die Nieren ausgeschieden. Eine intakte Blut-Hirn-Schranke überwindet er nicht, weshalb sich Hirnherde mit gestörter Schranke abheben.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen","Kopfschmerzen, Schwindel, Kribbeln (Parästhesien), Geschmacksstörungen","Hitzegefühl, Hautrötung","Juckreiz, Hautausschlag, Nesselsucht","Reaktionen an der Injektionsstelle","Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock, Kehlkopfkrampf","Krampfanfälle, Herzrhythmusstörungen","Nephrogene systemische Fibrose (Verhärtung von Haut und Bindegewebe) bei schwerer Niereninsuffizienz"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt notwendig ist; Gadolinium kann die Plazenta passieren.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über. Ob das Stillen für 24 Stunden unterbrochen wird, entscheiden Ärztin oder Arzt und Mutter gemeinsam.","hinweise":["Vor der Untersuchung Nierenerkrankungen, Dialyse, Lebertransplantation, Allergien und frühere Kontrastmittelreaktionen angeben.","Nach der Injektion mindestens 30 Minuten unter Beobachtung bleiben.","Bei Nierenkranken: Hautverdickungen, Gelenksteifigkeit oder Schmerzen in den Wochen nach der Untersuchung ärztlich melden."],"darreichung":["Injektionslösung","Fertigspritze"]},"gadotersaeure":{"wirkmechanismus":"Verstärkt im MRT-Bild den Kontrast, sodass krankhafte Veränderungen und Gefässe deutlicher erkennbar werden. Gadotersäure ist ein Komplex des paramagnetischen Metalls Gadolinium mit dem ringförmigen (makrozyklischen) Liganden DOTA. Sie verkürzt die Relaxationszeiten, vor allem T1, der Wasserstoffkerne im Gewebe, das dadurch heller erscheint. Die makrozyklische Struktur bindet Gadolinium sehr stabil; die Ausscheidung erfolgt unverändert über die Nieren.","nebenwirkungen":{"gelegentlich":["Kopfschmerzen, Kribbeln (Parästhesie), Schwindel","Geschmacksstörung","Übelkeit, Bauchschmerzen","Blutdruckabfall oder -anstieg","Wärme- oder Kältegefühl, Reaktionen an der Injektionsstelle","Überempfindlichkeitsreaktionen"],"selten":["Erbrechen, Durchfall","Nesselsucht, Juckreiz, Hautausschlag, Schwitzen","Angst","Herzklopfen","Lidschwellung"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle, Ohnmacht, Koma","Herzrhythmusstörungen, Herzstillstand","Bronchospasmus, Kehlkopfschwellung","Angioödem (Schwellung von Haut und Schleimhäuten)"],"unbekannt":["Nephrogene systemische Fibrose (Verhärtung von Haut, Gelenken und Organen)","Gadoliniumablagerungen im Gehirn"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt nötig ist.","stillzeit":"Geht nur in sehr geringer Menge in die Muttermilch über. Ob nach der Untersuchung 24 Stunden lang nicht gestillt wird, entscheiden Ärztin oder Arzt und Mutter gemeinsam.","hinweise":["Vor der Untersuchung Nierenerkrankungen, frühere Kontrastmittelreaktionen, Allergien und Epilepsie angeben.","Nach der Injektion mindestens 30 Minuten unter Beobachtung bleiben; verzögerte Reaktionen können noch Tage später auftreten.","Bei Nierenschwäche: Hautverdickung, Schwellungen oder Gelenksteife in den Wochen nach der Untersuchung ärztlich melden."],"darreichung":["Injektionslösung (Durchstechflasche, Fertigspritze)"]},"gadoxetsaeure":{"wirkmechanismus":"Hellt in der MRT gesundes Lebergewebe auf, sodass Herde ohne funktionierende Leberzellen dunkel hervortreten. Das paramagnetische Gadolinium verkürzt die T1-Relaxationszeit; zunächst verteilt sich das Mittel wie andere Kontrastmittel in den Gefässen und im Extrazellulärraum. Danach wird rund die Hälfte über die Transporter OATP1B1/1B3 in die Leberzellen aufgenommen und über die Galle ausgeschieden, die andere Hälfte über die Nieren. Etwa 20 Minuten nach der Injektion entsteht so die leberspezifische (hepatobiliäre) Phase.","nebenwirkungen":{"unbekannt":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Geschmacks- oder Geruchsstörungen","Übelkeit, Erbrechen, Mundtrockenheit","Hitzegefühl, Hautrötung, Blutdruckanstieg","Juckreiz, Hautausschlag","Rückenschmerzen, Brustschmerzen, Reaktionen an der Injektionsstelle","Überempfindlichkeitsreaktionen bis zum anaphylaktischen Schock, Herzrasen, Unruhe","Nephrogene systemische Fibrose (Verhärtung von Haut und Bindegewebe) bei schwerer Niereninsuffizienz"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt notwendig ist; Gadolinium kann die Plazenta passieren.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über. Ob das Stillen für 24 Stunden unterbrochen wird, entscheiden Ärztin oder Arzt und Mutter gemeinsam.","hinweise":["Vor der Untersuchung Nieren- und Lebererkrankungen, Dialyse, Lebertransplantation, Allergien und Herzrhythmusstörungen angeben.","Nach der Injektion mindestens 30 Minuten unter Beobachtung bleiben."],"darreichung":["Injektionslösung","Fertigspritze"]},"galantamin":{"wirkmechanismus":"Verbessert bei Alzheimer-Demenz vorübergehend Gedächtnis und Alltagsfähigkeiten, indem es den Abbau des Botenstoffs Acetylcholin bremst. Galantamin, ursprünglich aus Schneeglöckchen gewonnen, hemmt selektiv, kompetitiv und reversibel die Acetylcholinesterase. Zusätzlich verstärkt es als allosterischer Modulator die Wirkung von Acetylcholin an nikotinischen Rezeptoren. Abgebaut wird es über CYP2D6 und CYP3A4.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen"],"haeufig":["Appetitminderung, Gewichtsabnahme","Halluzinationen, Depression","Schwindel, Zittern, Kopfschmerzen, Schläfrigkeit","Ohnmacht (Synkope), Stürze","Bradykardie (langsamer Puls), Bluthochdruck","Bauchschmerzen, Durchfall, Dyspepsie (Verdauungsbeschwerden)","Muskelkrämpfe","Müdigkeit, Schwäche"],"gelegentlich":["Überempfindlichkeitsreaktionen","Dehydratation (Flüssigkeitsmangel)","AV-Block 1. Grades, Herzklopfen, Extrasystolen","Tiefer Blutdruck, Hitzewallungen","Kribbeln, Geschmacksstörungen, verschwommenes Sehen, Ohrensausen","Vermehrtes Schwitzen, Muskelschwäche","Erhöhte Leberwerte","Krampfanfälle"],"selten":["Kompletter AV-Block","Hepatitis","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, akute generalisierte exanthematische Pustulose, Erythema multiforme)"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach strenger ärztlicher Abwägung.","stillzeit":"Nicht stillen.","hinweise":["Retardkapsel einmal täglich am Morgen mit dem Frühstück und reichlich Flüssigkeit einnehmen; während der Behandlung genug trinken.","Nach einem Unterbruch von mehreren Tagen mit der niedrigsten Dosis neu beginnen.","Vor einer Narkose die Einnahme angeben.","Bei Hautausschlag, Ohnmacht oder sehr langsamem Puls ärztlich abklären lassen."],"darreichung":["Retardkapseln"]},"galcanezumab":{"wirkmechanismus":"Beugt Migräneanfällen vor, indem es einen Botenstoff abfängt, der bei der Migräne Gefässerweiterung und Schmerz vermittelt. Galcanezumab ist ein humanisierter IgG4-Antikörper, der den Botenstoff CGRP (Calcitonin Gene-Related Peptide) selbst bindet und so dessen Andocken an den Rezeptor verhindert. Als Eiweiss wird es nicht über Leberenzyme (CYP) abgebaut; nach einer doppelten Startdosis genügt eine Injektion pro Monat.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Injektionsstelle","Reaktionen an der Injektionsstelle (Rötung, Juckreiz, Bluterguss, Schwellung)"],"haeufig":["Drehschwindel (Vertigo)","Obstipation (Verstopfung)","Pruritus (Juckreiz)","Hautausschlag"],"gelegentlich":["Nesselsucht (Urtikaria)"],"unbekannt":["Schwere allergische Reaktionen (Anaphylaxie, Angioödem)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; aus Vorsicht während der Schwangerschaft nicht anwenden.","stillzeit":"Unbekannt, ob Galcanezumab in die Muttermilch übergeht; besonders in den ersten Tagen nach der Geburt möglich – nur nach ärztlicher Abwägung.","hinweise":["Den Fertigpen vor der Injektion etwa 30 Minuten bei Raumtemperatur liegen lassen; im Kühlschrank lagern, nicht schütteln, nicht einfrieren.","Die Wirkung wird nach etwa 3 Monaten ärztlich beurteilt; Akutmittel gegen Migräneanfälle weiter wie verordnet verwenden.","Bei Atemnot, Schwellungen im Gesicht oder starkem Ausschlag – auch Tage nach der Spritze – sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung im Fertigpen (subkutan)"]},"gallium-68ga-gozetotid":{"wirkmechanismus":"Macht Krebsherde im PET-Bild sichtbar, ohne selbst zu behandeln. Gozetotid (PSMA-11) bindet mit hoher Affinität an das prostataspezifische Membranantigen (PSMA), das auf den meisten Prostatakrebszellen stark vermehrt vorkommt. Das gebundene Gallium-68 ist ein Positronenstrahler mit einer Halbwertszeit von rund 68 Minuten, dessen Strahlung die PET-Kamera erfasst. Der Kit wird unmittelbar vor der Anwendung in der Nuklearmedizin mit Gallium-68 markiert; die Ausscheidung erfolgt hauptsächlich über die Nieren.","nebenwirkungen":{"haeufig":["Müdigkeit (Fatigue)"],"gelegentlich":["Übelkeit","Erbrechen","Obstipation (Verstopfung)"],"unbekannt":["Durchfall, Mundtrockenheit","Reaktionen an der Injektionsstelle","Geringe Strahlenbelastung mit theoretisch leicht erhöhtem Langzeitrisiko für Krebs"]},"schwangerschaft":"Nicht zur Anwendung bei Frauen bestimmt.","stillzeit":"Nicht zur Anwendung bei Frauen bestimmt.","hinweise":["Wird nur in nuklearmedizinischen Zentren durch Fachpersonal hergestellt und gespritzt.","Vor und in den ersten Stunden nach der Untersuchung reichlich trinken und häufig Wasser lassen – das senkt die Strahlenbelastung.","Gallium-68 zerfällt rasch (Halbwertszeit rund 68 Minuten); die Radioaktivität ist nach wenigen Stunden weitgehend abgeklungen."],"darreichung":["Kit zur Herstellung einer radioaktiven Injektionslösung"]},"galsulfase":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich Zuckerketten (Dermatansulfat) nicht mehr in Knochen, Gelenken, Herz, Lunge und anderen Organen anhäufen. Galsulfase ist eine gentechnisch hergestellte N-Acetylgalactosamin-4-Sulfatase (Arylsulfatase B). Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und spaltet in den Lysosomen Sulfatgruppen vom Dermatansulfat ab. Dadurch sinkt die Ausscheidung von Glykosaminoglykanen im Urin, und die körperliche Belastbarkeit kann sich bessern.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen","Kopfschmerzen","Fieber, Schüttelfrost, Schmerzen, Unwohlsein","Übelkeit, Erbrechen, Bauchschmerzen","Atemnot, verstopfte Nase","Bluthochdruck","Gelenkschmerzen"],"unbekannt":["Anaphylaxie, Schock","Bronchospasmus (Verkrampfung der Atemwege), Atemstillstand, Blauverfärbung der Haut (Zyanose)","Blutdruckabfall, verlangsamter oder beschleunigter Puls","Nesselsucht, Hautrötung, Kribbeln"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Nicht bekannt, ob Galsulfase in die Muttermilch übergeht. Stillen nur nach ärztlicher Abwägung.","hinweise":["Wird wöchentlich als Infusion in eine Vene gegeben (über mehrere Stunden), meist nach Vorbehandlung mit einem Antihistaminikum.","Bei Fieber oder Atemwegsinfekt vor der Infusion das Behandlungsteam informieren.","Neue Nackenschmerzen, Kribbeln oder Schwäche in Armen oder Beinen sofort melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"ganciclovir":{"wirkmechanismus":"Hemmt die Vermehrung von Herpesviren wie dem Zytomegalievirus. Ganciclovir ist ein Abkömmling des Erbgutbausteins Guanosin; in infizierten Zellen wird es zuerst durch ein virales Enzym (beim CMV die Proteinkinase UL97, bei Herpes-simplex die Thymidinkinase) und dann durch zelluläre Enzyme zu Ganciclovir-Triphosphat aktiviert. Dieses hemmt die virale DNA-Polymerase und führt nach Einbau zum Abbruch der viralen DNA-Kette. Weil es auch menschliche Zellen schädigen kann, wirkt es knochenmarkhemmend und im Tierversuch erbgut- und fruchtschädigend.","nebenwirkungen":{"sehrHaeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Anämie (Blutarmut)","Durchfall","Atemnot (Dyspnoe)"],"haeufig":["Thrombozytopenie, Leukopenie, Panzytopenie","Infektionen (z. B. Sepsis, Candida-Infektionen)","Kopfschmerzen, Schlaflosigkeit, Schwindel, Kribbeln, Krampfanfälle; Depression, Angst, Verwirrtheit","Übelkeit, Erbrechen, Bauchschmerzen, Appetitlosigkeit","Erhöhte Leberwerte, Nierenfunktionsstörung","Fieber, Müdigkeit, Juckreiz, nächtliches Schwitzen","Makulaödem, Netzhautablösung, Glaskörpertrübungen","Augengel: Brennen, Stechen, Augenreizung, verschwommenes Sehen"],"gelegentlich":["Knochenmarkversagen","Anaphylaktische Reaktion","Halluzinationen, psychotische Störungen, Unruhe","Herzrhythmusstörungen","Haarausfall, Nesselsucht","Nierenversagen","Männliche Unfruchtbarkeit"],"selten":["Aplastische Anämie, Agranulozytose"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; nur bei zwingender Notwendigkeit anwenden. Frauen müssen während und mindestens 30 Tage nach der Behandlung, Männer während und mindestens 90 Tage danach (Kondom) verhüten.","stillzeit":"Infusion: kontraindiziert, abstillen. Augengel: nur nach ärztlicher Abwägung.","hinweise":["Das Blutbild wird regelmässig kontrolliert, zu Beginn häufig.","Zuverlässig verhüten: Frauen bis 30 Tage, Männer bis 90 Tage nach Behandlungsende.","Augengel: Kontaktlinsen während der Behandlung nicht tragen; nach dem Eintropfen kann die Sicht kurz verschwommen sein (Fahrtüchtigkeit)."],"darreichung":["Pulver zur Herstellung einer Infusionslösung","Augengel"]},"ganirelix":{"wirkmechanismus":"Verhindert, dass der Eisprung zu früh ausgelöst wird, bevor die Eizellen entnommen werden können. Ganirelix blockiert als Gegenspieler (Antagonist) die GnRH-Rezeptoren der Hirnanhangdrüse. Dadurch wird die Ausschüttung von luteinisierendem Hormon (LH) und in geringerem Mass von follikelstimulierendem Hormon (FSH) rasch und umkehrbar unterdrückt – ohne den anfänglichen Hormonanstieg, den GnRH-Agonisten auslösen.","nebenwirkungen":{"sehrHaeufig":["Hautreaktionen an der Einstichstelle (vor allem Rötung, mit oder ohne Schwellung)"],"gelegentlich":["Kopfschmerzen","Übelkeit","Unwohlsein"],"sehrSelten":["Überempfindlichkeitsreaktionen wie Ausschlag, Gesichtsschwellung, Atemnot bis zur Anaphylaxie"],"unbekannt":["Im Rahmen der Stimulationsbehandlung: Unterleibsschmerzen, Blähbauch, ovarielles Überstimulationssyndrom, Eileiterschwangerschaft, Fehlgeburt"]},"schwangerschaft":"Kontraindiziert; die Behandlung erfolgt vor einer möglichen Schwangerschaft.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich etwa zur gleichen Tageszeit unter die Haut spritzen, vorzugsweise am Oberschenkel; Einstichstelle wechseln.","Vergessene Dosen sofort dem Behandlungsteam melden – es droht ein vorzeitiger Eisprung."],"darreichung":["Fertigspritze (Injektionslösung zur Anwendung unter die Haut)"]},"garadacimab":{"wirkmechanismus":"Setzt am Anfang der Kette an, die beim erblichen Angioödem zu Schwellungen führt. Garadacimab ist ein vollständig humaner monoklonaler Antikörper, der den aktivierten Gerinnungsfaktor XII (Faktor XIIa) bindet und hemmt. Dadurch wird das Kontaktsystem nicht aktiviert: Es entsteht weniger Plasmakallikrein und in der Folge weniger Bradykinin, das die Gefässe durchlässig macht. Wegen der langen Halbwertszeit genügt eine Injektion pro Monat.","nebenwirkungen":{"haeufig":["Reaktionen an der Injektionsstelle (Rötung, Bluterguss, Juckreiz, Quaddeln, Schmerz)"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber während der Schwangerschaft möglichst nicht anwenden.","stillzeit":"Nicht bekannt, ob Garadacimab in die Muttermilch übergeht; Antikörper gehen in den ersten Tagen nach der Geburt über – Anwendung nach ärztlicher Abwägung.","hinweise":["Nach Schulung selbst mit dem Fertigpen unter die Haut spritzen; im Kühlschrank lagern.","Für akute Attacken trotzdem immer ein Notfallmedikament mitführen.","Vor Gerinnungstests auf die Behandlung hinweisen (verlängerte aPTT)."],"darreichung":["Injektionslösung im Fertigpen (unter die Haut)"]},"gefitinib":{"wirkmechanismus":"Blockiert ein Enzym, über das Krebszellen mit verändertem EGFR Wachstumssignale erhalten. Gefitinib hemmt reversibel und selektiv die Tyrosinkinase des epidermalen Wachstumsfaktor-Rezeptors (EGFR), indem es mit ATP um die Bindungsstelle konkurriert. Bei Tumoren mit aktivierenden EGFR-Mutationen (z. B. Exon-19-Deletion, L858R) ist die Wirkung besonders stark; die Resistenzmutation T790M macht es unwirksam.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit, Erbrechen, Stomatitis (Mundschleimhautentzündung)","Appetitlosigkeit","Hautausschlag (oft akneähnlich), Juckreiz, trockene Haut","Erhöhte Leberwerte","Schwäche (Asthenie)"],"haeufig":["Interstitielle Lungenerkrankung (teils tödlich)","Bindehautentzündung, Lidrandentzündung, trockene Augen","Nagelveränderungen, Haarausfall","Flüssigkeitsmangel (Dehydratation), Mundtrockenheit","Blutungen wie Nasenbluten oder Blut im Urin","Eiweiss im Urin, erhöhtes Kreatinin","Fieber"],"gelegentlich":["Keratitis (Hornhautentzündung), Hornhautdefekte","Hepatitis (Leberentzündung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Magen-Darm-Durchbruch (Perforation)"],"selten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme (schwere Hautreaktionen)","Hämorrhagische Zystitis (blutige Blasenentzündung)","Hautgefässentzündung (Vaskulitis)"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter sollen während der Behandlung nicht schwanger werden.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit, unabhängig von den Mahlzeiten; die Tablette kann bei Schluckproblemen in Wasser zerfallen gelassen werden.","Plötzliche Atemnot, Husten oder Fieber sofort ärztlich melden.","Leberwerte regelmässig kontrollieren lassen.","Vor der Einnahme von Säureblockern oder Antazida in der Apotheke oder ärztlich beraten lassen."],"darreichung":["Filmtabletten"]},"gelatine-succinyliert":{"wirkmechanismus":"Füllt das Blutgefässsystem auf, wenn zu wenig Blutvolumen vorhanden ist. Succinylierte Gelatine besteht aus abgebauten, chemisch veränderten Eiweissketten aus Rinderkollagen, die wegen ihrer Grösse vorübergehend in den Blutgefässen bleiben und dort durch kolloidosmotischen Druck Flüssigkeit binden. Die Volumenwirkung entspricht etwa der infundierten Menge und hält einige Stunden an; die Gelatine wird hauptsächlich über die Nieren ausgeschieden.","nebenwirkungen":{"selten":["Allergische (anaphylaktoide) Reaktionen wie Hautausschlag, Nesselsucht, Blutdruckabfall"],"sehrSelten":["Schwere anaphylaktische Reaktionen bis zum Schock (schwere allergische Reaktion)"],"unbekannt":["Volumenüberlastung mit Atemnot und Lungenödem","Verdünnung von Blutzellen und Gerinnungsfaktoren (Verdünnungskoagulopathie)","Fieber, Schüttelfrost"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden; eine allergische Reaktion mit Blutdruckabfall bei der Mutter kann dem Ungeborenen schaden.","stillzeit":"Nur bei klarer Notwendigkeit anwenden; Daten fehlen.","hinweise":["Wird im Spital oder im Rettungsdienst als Infusion gegeben; die ersten Milliliter langsam und unter Beobachtung (Allergiegefahr).","Hämatokrit, Elektrolyte, Gerinnung und Flüssigkeitsbilanz werden kontrolliert.","Eine bekannte Allergie auf rotes Fleisch (Alpha-Gal-Syndrom) unbedingt angeben."],"darreichung":["Infusionslösung"]},"gelbfieber-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, einen lang anhaltenden Schutz gegen das Gelbfiebervirus aufzubauen. Der Impfstoff enthält lebende, abgeschwächte Gelbfieberviren (Stamm 17D-204), die in Hühnerembryonen gezüchtet werden. Nach einer einzigen Dosis bilden über 90 % der Geimpften innerhalb von etwa 10 Tagen schützende neutralisierende Antikörper.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Schmerzen an der Einstichstelle","Schwäche (Asthenie)","Muskelschmerzen","Bei Kleinkindern: Reizbarkeit, Weinen, Appetitlosigkeit, Schläfrigkeit"],"haeufig":["Fieber","Übelkeit, Erbrechen, Durchfall","Gelenkschmerzen","Rötung, Schwellung oder Bluterguss an der Einstichstelle"],"gelegentlich":["Schwindel","Bauchschmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion), Angioödem","Neurotrope Erkrankung (YEL-AND): Hirn- oder Hirnhautentzündung, Guillain-Barré-Syndrom – sehr selten, häufiger ab 60 Jahren","Viszerotrope Erkrankung (YEL-AVD): gelbfieberähnliche Erkrankung mit Organversagen, oft tödlich – sehr selten, häufiger ab 60 Jahren","Lymphknotenschwellung","Hautausschlag, Nesselsucht"]},"schwangerschaft":"Grundsätzlich nicht impfen; nur wenn eine Reise in ein Gebiet mit hohem Ansteckungsrisiko unvermeidbar ist, nach strenger ärztlicher Abwägung.","stillzeit":"Nicht impfen: Übertragung des Impfvirus auf gestillte Säuglinge mit Hirnentzündung wurde beschrieben. Nur bei unvermeidbarem hohem Risiko nach ärztlicher Abwägung.","hinweise":["Impfung nur in anerkannten Gelbfieber-Impfzentren; Eintrag im internationalen Impfzertifikat, gültig ab dem 10. Tag nach der Impfung.","Eine Dosis schützt meist lebenslang; in bestimmten Situationen (z. B. Impfung vor dem 2. Geburtstag, in der Schwangerschaft oder bei HIV) wird eine Auffrischung empfohlen.","Bei hohem Fieber, Gelbsucht, starken Kopfschmerzen, Verwirrtheit oder Lähmungen in den Wochen nach der Impfung sofort ärztliche Hilfe holen.","Mückenschutz bleibt wichtig, da in denselben Gebieten weitere von Mücken übertragene Krankheiten vorkommen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionssuspension"]},"gemcitabin":{"wirkmechanismus":"Hemmt die Teilung von Krebszellen, indem es sich als falscher Baustein in das Erbgut einschleust. Gemcitabin ist ein Analogon des Nukleosids Desoxycytidin und wird in der Zelle zu Di- und Triphosphat umgewandelt. Das Diphosphat hemmt die Ribonukleotid-Reduktase und verknappt so die natürlichen DNA-Bausteine; das Triphosphat wird in die DNA eingebaut und stoppt deren Verlängerung. Die Wirkung ist auf Zellen in der Teilungsphase (S-Phase) gerichtet.","nebenwirkungen":{"sehrHaeufig":["Leukopenie, Thrombozytopenie, Anämie (Blutbildveränderungen)","Atemnot (meist leicht)","Übelkeit, Erbrechen","Erhöhte Leberwerte","Hautausschlag mit Juckreiz, Haarausfall","Blut und Eiweiss im Urin","Grippeähnliche Beschwerden (Fieber, Kopf-, Rücken- und Gliederschmerzen, Schüttelfrost)","Wassereinlagerungen (Ödeme)"],"haeufig":["Fieber bei Neutropenie","Appetitlosigkeit","Schlaflosigkeit, Schläfrigkeit","Husten, Schnupfen","Durchfall, Verstopfung, Mundschleimhautentzündung","Erhöhtes Bilirubin","Schwitzen"],"gelegentlich":["Interstitielle Pneumonitis (Lungenentzündung), Bronchospasmus","Herzinsuffizienz, Herzrhythmusstörungen","Schlaganfall","Nierenversagen","Hämolytisch-urämisches Syndrom (Blutzerfall mit Nierenversagen)","Schwere Leberschäden bis Leberversagen"],"selten":["Herzinfarkt","Gefässentzündungen mit Durchblutungsstörungen an Fingern und Zehen bis zum Absterben (Gangrän)","Lungenödem, akutes Atemnotsyndrom (ARDS)","Schwere Hautreaktionen mit Blasenbildung und Schuppung","Strahlenreaktionen in bestrahlten Bereichen","Blutdruckabfall"],"sehrSelten":["Kapillarlecksyndrom (Flüssigkeitsaustritt aus den Gefässen)","Ischämische Kolitis (Darmentzündung durch Minderdurchblutung)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Anaphylaktoide Reaktion","Posteriores reversibles Enzephalopathie-Syndrom (PRES, Hirnschwellung mit Kopfschmerzen, Sehstörungen, Krämpfen)"],"unbekannt":["Pseudozellulitis (Hautrötung ähnlich einer Wundrose)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und einige Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Vor jeder Gabe Kontrolle von Blutbild sowie Leber- und Nierenwerten.","Bei Atemnot, Husten, Fieber, Blutungen, deutlicher Gewichtszunahme oder Schwellungen ärztlich melden.","Kann schläfrig machen – Vorsicht beim Autofahren und Bedienen von Maschinen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung","Konzentrat zur Herstellung einer Infusionslösung"]},"gemfibrozil":{"wirkmechanismus":"Senkt vor allem die Triglyceride im Blut und erhöht das HDL-Cholesterin. Gemfibrozil aktiviert den Kernrezeptor PPAR-alpha; dadurch wird die Lipoproteinlipase aktiviert und der Abbau triglyceridreicher Lipoproteine (VLDL) gesteigert. Gleichzeitig bildet die Leber weniger VLDL, und aus dem Fettgewebe werden weniger freie Fettsäuren freigesetzt. Gemfibrozil und sein Glucuronid hemmen zudem stark das Enzym CYP2C8 und den Leber-Aufnahmetransporter OATP1B1, was zahlreiche Wechselwirkungen erklärt.","nebenwirkungen":{"sehrHaeufig":["Dyspepsie (Verdauungsbeschwerden)"],"haeufig":["Bauchschmerzen, Übelkeit, Erbrechen","Durchfall, Blähungen, Verstopfung","Kopfschmerzen, Drehschwindel (Vertigo)","Hautausschlag, Ekzem","Müdigkeit"],"gelegentlich":["Vorhofflimmern"],"selten":["Gallensteine, Gallenblasenentzündung, cholestatische Gelbsucht","Hepatitis (Leberentzündung), veränderte Leberwerte","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie), Knochenmarkhypoplasie","Myositis und Rhabdomyolyse (Muskelzerfall), Muskel- und Gelenkschmerzen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem (Schwellung von Haut und Schleimhäuten), Nesselsucht","Lichtempfindlichkeit der Haut, Haarausfall","Erektionsstörung, Kribbeln (Parästhesien), Depression, verschwommenes Sehen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn es nach strenger ärztlicher Abwägung eindeutig notwendig ist.","stillzeit":"Es ist nicht bekannt, ob Gemfibrozil in die Muttermilch übergeht; während der Stillzeit nicht anwenden.","hinweise":["Etwa 30 Minuten vor dem Frühstück bzw. vor dem Abendessen einnehmen.","Unerklärliche Muskelschmerzen, Muskelschwäche oder dunklen Urin sofort ärztlich melden.","Blutbild, Leberwerte und Blutfette vor und während der Behandlung kontrollieren; ohne ausreichende Wirkung nach 3 Monaten absetzen.","Starker CYP2C8-Hemmer: jedes neue Medikament auf Wechselwirkungen prüfen lassen."],"darreichung":["Filmtabletten"]},"gemtuzumab-ozogamicin":{"wirkmechanismus":"Bringt ein starkes Zellgift gezielt in Leukämiezellen. Der humanisierte Antikörper bindet an CD33, ein Oberflächenmolekül, das auf den meisten AML-Zellen vorkommt, und wird mitsamt dem angehängten Calicheamicin-Derivat in die Zelle aufgenommen. Dort wird das Calicheamicin freigesetzt, bricht die DNA-Doppelstränge und löst den Zelltod aus.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Febrile Neutropenie, Thrombozytopenie, Anämie, Leukopenie","Blutungen","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen, Mundschleimhautentzündung, Verstopfung","Erhöhte Leberwerte, Hyperbilirubinämie (erhöhtes Bilirubin)","Hautausschlag","Fieber, Ödeme, Müdigkeit, Schüttelfrost","Appetitlosigkeit, Hyperglykämie (erhöhter Blutzucker)"],"haeufig":["Venenverschlusskrankheit der Leber (VOD / sinusoidales Obstruktionssyndrom)","Tumorlysesyndrom","Infusionsreaktionen","Blutdruckabfall oder -anstieg","Aszites (Bauchwassersucht)","Multiorganversagen"],"gelegentlich":["Leberversagen","Budd-Chiari-Syndrom (Verschluss der Lebervenen)"]},"schwangerschaft":"Nicht anwenden: Im Tierversuch wurde das Ungeborene geschädigt. Frauen verhüten während der Behandlung und mindestens 7 Monate danach, Männer mit Partnerin mindestens 4 Monate danach.","stillzeit":"Während der Behandlung und mindestens 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Wird im Spital als Infusion gegeben, mit Prämedikation gegen Infusionsreaktionen.","Rasche Gewichtszunahme, Schmerzen im rechten Oberbauch, Gelbsucht oder Bauchschwellung sofort melden (Hinweis auf Leberschaden).","Fieber, Infektzeichen oder Blutungen sofort melden.","Regelmässige Kontrollen von Blutbild und Leberwerten."],"darreichung":["Pulver für ein Infusionskonzentrat"]},"gentamicin":{"wirkmechanismus":"Tötet Bakterien ab, indem es ihre Eiweissherstellung stört. Gentamicin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und führt zu Ablesefehlern; die fehlerhaften Eiweisse schädigen die Bakterienmembran. Die Wirkung ist konzentrationsabhängig, daher wird es meist einmal täglich in hoher Dosis gegeben. Es wirkt vor allem gegen gramnegative Bakterien und zusammen mit Betalaktamen synergistisch gegen Streptokokken, Enterokokken und Staphylokokken. Lokal eingelegt erreicht es hohe Spiegel am Infektionsort bei geringer Aufnahme ins Blut.","nebenwirkungen":{"haeufig":["Eingeschränkte Nierenfunktion (meist reversibel)"],"gelegentlich":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Superinfektion mit resistenten Keimen"],"selten":["Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie, Eosinophilie)","Elektrolytstörungen (Kalium-, Calcium- und Magnesiummangel), Appetitlosigkeit","Polyneuropathie, Kribbeln","Übelkeit, Erbrechen, Mundschleimhautentzündung","Erhöhte Leberwerte","Muskelschmerzen, Fieber"],"sehrSelten":["Akutes Nierenversagen","Anaphylaxie (schwere allergische Reaktion)","Verwirrtheit, Halluzinationen, Krampfanfälle, neuromuskuläre Blockade","Hörverlust, Tinnitus, Drehschwindel","Antibiotika-assoziierte Kolitis","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Bleibender Hörverlust bis zur Taubheit, bleibende Gleichgewichtsstörungen"]},"schwangerschaft":"Geht über die Plazenta und kann beim Kind bleibende Innenohr- und Nierenschäden verursachen. Nur bei lebensbedrohlicher Infektion ohne Alternative anwenden.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling kaum aufgenommen; Durchfall und Pilzbefall beim Kind möglich. Nur nach ärztlicher Abwägung.","hinweise":["Während der Infusionstherapie werden Blutspiegel, Nierenwerte und bei längerer Behandlung das Gehör kontrolliert.","Hörminderung, Ohrensausen oder Schwindel sofort melden – auch noch Wochen nach der Behandlung.","Ausreichend trinken, sofern ärztlich nicht anders verordnet."],"darreichung":["Injektions- und Infusionslösung","Kollagenschwamm zum Einlegen (Implantat)","Ketten zum Einlegen in Knochen und Weichteile","Creme und Salbe (Kombination mit Kortison)"]},"gilteritinib":{"wirkmechanismus":"Bremst die Vermehrung von Leukämiezellen, die durch ein verändertes Enzym angetrieben werden. Gilteritinib hemmt die Rezeptor-Tyrosinkinase FLT3 – sowohl mit ITD- als auch mit TKD-Mutation (z. B. D835) – sowie die Kinase AXL. Dadurch werden Signale für Zellteilung und Überleben blockiert, und die Leukämiezellen sterben ab.","nebenwirkungen":{"sehrHaeufig":["Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase) und erhöhte Kreatinkinase (Muskelenzym)","Durchfall, Übelkeit, Verstopfung","Müdigkeit, Schwäche","Husten, Atemnot","Periphere Ödeme (Wassereinlagerungen)","Schwindel, Blutdruckabfall","Gelenk-, Muskel- und Gliederschmerzen"],"haeufig":["Differenzierungssyndrom (potenziell lebensbedrohlich)","QT-Verlängerung im EKG","Herzinsuffizienz, Perikarderguss, Perikarditis (Herzbeutelentzündung)","Anaphylaktische Reaktion (schwere allergische Reaktion)","Akutes Nierenversagen","Bauchschmerzen, Stomatitis (Mundschleimhautentzündung)"],"gelegentlich":["Posteriores reversibles Enzephalopathie-Syndrom (PRES)"],"unbekannt":["Pankreatitis (Bauchspeicheldrüsenentzündung)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nicht anwenden. Frauen müssen während der Behandlung und mindestens 6 Monate danach, Männer mit Partnerin im gebärfähigen Alter mindestens 4 Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens 2 Monate danach nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit, mit oder ohne Mahlzeit; Tabletten unzerkaut schlucken.","Fieber, Atemnot, rasche Gewichtszunahme oder Schwellungen sofort melden (Differenzierungssyndrom).","EKG, Blutwerte und Elektrolyte werden regelmässig kontrolliert.","Kein Johanniskraut; neue Medikamente nur nach Rücksprache."],"darreichung":["Filmtabletten"]},"ginkgo":{"wirkmechanismus":"Soll die Durchblutung und die Funktion der Nervenzellen verbessern. Der standardisierte Spezialextrakt enthält Flavonglykoside und Terpenlaktone (Ginkgolide, Bilobalid). Im Labor verbessert er die Fliesseigenschaften des Blutes, hemmt den plättchenaktivierenden Faktor (PAF), fängt freie Radikale ab und schützt Nervenzellen vor Sauerstoffmangel. Welche Inhaltsstoffe für die klinische Wirkung entscheidend sind, ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schwindel, Benommenheit","Durchfall, Bauchschmerzen","Übelkeit, Erbrechen"],"unbekannt":["Blutungen an einzelnen Organen (z. B. Auge, Nase, Gehirn, Magen-Darm-Trakt), vor allem zusammen mit Blutverdünnern","Überempfindlichkeitsreaktionen bis zum allergischen Schock","Allergische Hautreaktionen (Rötung, Schwellung, Juckreiz)"]},"schwangerschaft":"Kontraindiziert, da Ginkgo-Extrakt die Blutungsneigung erhöhen kann und keine ausreichenden Daten vorliegen.","stillzeit":"Nicht empfohlen, da keine ausreichenden Daten vorliegen.","hinweise":["Vor Operationen und Zahnbehandlungen die Einnahme angeben.","Die Wirkung ist erst nach mehreren Wochen beurteilbar; nach etwa 3 Monaten überprüfen, ob die Behandlung weiter sinnvoll ist.","Zusammen mit Blutverdünnern nur nach ärztlicher Rücksprache einnehmen."],"darreichung":["Filmtabletten","Tropfen"]},"ginseng":{"wirkmechanismus":"Soll die körperliche und geistige Leistungsfähigkeit bei Erschöpfung unterstützen. Als wirksamkeitsbestimmend gelten die Ginsenoside (Saponine) aus der Wurzel von Panax ginseng, die in Untersuchungen u. a. Stoffwechsel, Stressreaktion und Durchblutung beeinflussen. Der genaue Wirkmechanismus ist nicht geklärt; die Anwendung beruht wesentlich auf langjähriger Erfahrung.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Durchfall, Bauchschmerzen)","Schlafstörungen, Nervosität","Kopfschmerzen","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"]},"schwangerschaft":"Nicht empfohlen, da keine ausreichenden Daten vorliegen.","stillzeit":"Nicht empfohlen, da keine ausreichenden Daten vorliegen.","hinweise":["Bei Schlafstörungen nicht am Abend einnehmen.","Bei Kombipräparaten mit Vitaminen und Mineralstoffen die Gesamtzufuhr beachten (z. B. Vitamin A, Eisen).","Bessern sich die Beschwerden nach einigen Wochen nicht, ärztlich abklären lassen."],"darreichung":["Kapseln"]},"givosiran":{"wirkmechanismus":"Verhindert in der Leber die übermässige Bildung von Stoffen, die Porphyrie-Attacken auslösen. Givosiran ist eine kleine interferierende RNA (siRNA), die über eine Zuckerverbindung (GalNAc) gezielt in Leberzellen aufgenommen wird. Dort führt sie zum Abbau der Boten-RNA der Aminolävulinsäure-Synthase 1 (ALAS1), des geschwindigkeitsbestimmenden Enzyms der Hämbildung. Dadurch sinken die nervenschädigenden Zwischenprodukte Aminolävulinsäure (ALA) und Porphobilinogen (PBG), und es treten weniger Attacken auf.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Reaktionen an der Injektionsstelle","Hautausschlag, Hautrötung, Juckreiz","Verschlechterung der Nierenfunktion (Kreatininanstieg)","Müdigkeit"],"haeufig":["Überempfindlichkeitsreaktionen","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Erhöhtes Homocystein im Blut"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach ärztlicher Abwägung von Nutzen und Risiko.","stillzeit":"Über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Wird einmal monatlich von einer Fachperson unter die Haut gespritzt; danach Beobachtung auf allergische Reaktionen.","Regelmässige Kontrollen von Leberwerten, Nierenfunktion und Homocystein.","Bekannte Auslöser von Porphyrie-Attacken (bestimmte Medikamente, Alkohol, Fasten) weiterhin meiden."],"darreichung":["Injektionslösung"]},"glasdegib":{"wirkmechanismus":"Hemmt den Hedgehog-Signalweg, über den sich Leukämie-Stammzellen erneuern und vor Chemotherapie schützen. Glasdegib bindet an das Membranprotein Smoothened (SMO) und verhindert die Aktivierung der GLI-Transkriptionsfaktoren. Zusammen mit niedrig dosiertem Cytarabin verlängert dies das Überleben im Vergleich zu Cytarabin allein.","nebenwirkungen":{"sehrHaeufig":["Anämie, Thrombozytopenie und fieberhafte Neutropenie (zusammen mit Cytarabin)","Blutungen","Übelkeit, Appetitlosigkeit","Müdigkeit","Muskelkrämpfe, Muskel- und Knochenschmerzen","Geschmacksstörungen","Periphere Ödeme (Wassereinlagerungen)","Lungenentzündung"],"haeufig":["QT-Verlängerung im EKG","Vorhofflimmern","Haarausfall"]},"schwangerschaft":"Nicht anwenden – im Tierversuch schwer fruchtschädigend. Frauen verhüten während und mindestens 30 Tage nach der letzten Dosis; Männer verwenden Kondome (auch nach Vasektomie) bis mindestens 30 Tage danach.","stillzeit":"Während der Behandlung und mindestens 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["EKG und Elektrolyte vor Beginn, etwa eine Woche nach Beginn und danach regelmässig kontrollieren.","Einmal täglich etwa zur gleichen Zeit einnehmen, mit oder ohne Essen.","Kein Blut spenden während und mindestens 30 Tage nach der Behandlung; Männer keine Samenspende.","Herzklopfen, Schwindel oder Ohnmacht sofort melden."],"darreichung":["Filmtabletten"]},"glatirameracetat":{"wirkmechanismus":"Lenkt das Immunsystem so um, dass es das Nervensystem weniger angreift. Glatirameracetat ist ein Gemisch synthetischer Eiweissketten aus vier Aminosäuren (Glutaminsäure, Lysin, Alanin, Tyrosin), das dem Myelin-Basisprotein der Nervenhüllen ähnelt. Es fördert regulatorische, entzündungshemmende T-Zellen (Th2-Typ), die im Gehirn die Entzündung dämpfen. Die genaue Wirkweise ist nicht vollständig geklärt.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle (Rötung, Schmerzen, Schwellung, Juckreiz, Verhärtung)","Sofortreaktion nach der Injektion mit Hitzegefühl (Flush), Brustschmerzen, Herzklopfen oder Atemnot (meist harmlos, klingt rasch ab)","Infektionen, Grippe","Angst, Depression","Kopfschmerzen","Übelkeit","Hautausschlag","Gelenk- und Rückenschmerzen, Schwäche"],"haeufig":["Lipoatrophie (Schwund von Unterhautfettgewebe an den Einstichstellen)","Lymphknotenschwellung","Überempfindlichkeitsreaktionen","Herzrasen (Tachykardie)","Erbrechen","Ödeme (Wassereinlagerungen), Gewichtszunahme","Fieber, Schüttelfrost"],"gelegentlich":["Hautnekrose (abgestorbene Haut) an der Einstichstelle","Krampfanfälle"],"selten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Leberschäden, autoimmune Hepatitis bis Leberversagen"]},"schwangerschaft":"Kann nach ärztlicher Abwägung bei klinischem Bedarf während der Schwangerschaft angewendet werden; bisherige Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Glatirameracetat wird kaum in die Muttermilch abgegeben und im Darm des Säuglings abgebaut; Stillen ist nach ärztlicher Abwägung möglich.","hinweise":["Einstichstellen täglich wechseln, um Hautschäden und Fettgewebsschwund zu vermeiden.","Die Sofortreaktion nach der Spritze (Hitze, Herzklopfen, Atemnot) klingt meist in Minuten ab; bei starken oder anhaltenden Beschwerden ärztliche Hilfe holen.","Bei Gelbsucht, dunklem Urin oder Juckreiz am ganzen Körper ärztlich abklären lassen (Leber).","Im Kühlschrank lagern; bis zu 1 Monat bei Raumtemperatur möglich."],"darreichung":["Injektionslösung (Fertigspritze)"]},"glecaprevir-pibrentasvir":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-C-Virus an zwei Stellen. Glecaprevir blockiert die virale NS3/4A-Protease, die das Vorläufer-Eiweiss des Virus in funktionsfähige Teile zerschneidet. Pibrentasvir hemmt das Virusprotein NS5A, das für die Vervielfältigung des Virus-Erbguts und den Zusammenbau neuer Viren nötig ist. Beide Wirkstoffe werden kaum über die Niere ausgeschieden; sie hemmen die Transporter P-Glykoprotein, BCRP und OATP1B und erhöhen so die Spiegel mancher anderer Arzneimittel.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Müdigkeit"],"haeufig":["Durchfall","Übelkeit","Schwäche (Asthenie)"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)"],"unbekannt":["Juckreiz","Reaktivierung einer Hepatitis B","Leberdekompensation bis Leberversagen bei fortgeschrittener Zirrhose"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; vorsichtshalber in der Schwangerschaft nicht anwenden.","stillzeit":"Ein Risiko für das gestillte Kind kann nicht ausgeschlossen werden – Entscheidung nach ärztlicher Abwägung, in der Regel während der Therapie nicht stillen.","hinweise":["Die Tagesdosis (bei Erwachsenen 3 Tabletten) einmal täglich gemeinsam zu einer Mahlzeit einnehmen.","Kombinierte Pille, Vaginalring oder Verhütungspflaster mit Ethinylestradiol sind während der Therapie nicht erlaubt.","Alle Medikamente angeben – insbesondere Cholesterinsenker, Gerinnungshemmer, Antiepileptika und HIV-Mittel."],"darreichung":["Filmtabletten"]},"glibenclamid":{"wirkmechanismus":"Senkt den Blutzucker, indem es die Bauchspeicheldrüse zur Ausschüttung von Insulin anregt. Glibenclamid bindet an den Sulfonylharnstoff-Rezeptor (SUR1) der ATP-abhängigen Kaliumkanäle in den Betazellen und schliesst diese Kanäle. Dadurch wird die Zellmembran depolarisiert, Calcium strömt ein und Insulin wird freigesetzt – unabhängig von der aktuellen Blutzuckerhöhe, weshalb Unterzuckerungen möglich sind. Voraussetzung ist eine noch vorhandene eigene Insulinproduktion; die Wirkung hält lange an.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung)"],"gelegentlich":["Übelkeit, Druck- oder Völlegefühl im Magen, Bauchschmerzen, Durchfall","Hautausschlag, Juckreiz, Nesselsucht"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)","Erhöhte Leberwerte"],"sehrSelten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Hämolytische Anämie (Blutarmut durch Zerfall roter Blutkörperchen)","Leberentzündung, Gallenstau (Cholestase)","Allergische Gefässentzündung (Vaskulitis)"],"unbekannt":["Gewichtszunahme","Vorübergehende Sehstörungen zu Behandlungsbeginn","Lichtempfindlichkeit der Haut","Hyponatriämie (Natriummangel)"]},"schwangerschaft":"Kontraindiziert. Ein Diabetes in der Schwangerschaft wird mit Insulin behandelt; bei Kinderwunsch rechtzeitig umstellen.","stillzeit":"Kontraindiziert; während der Stillzeit wird auf Insulin umgestellt.","hinweise":["Vor dem Frühstück bzw. der ersten Hauptmahlzeit einnehmen und keine Mahlzeit auslassen.","Zeichen einer Unterzuckerung (Schwitzen, Zittern, Heisshunger, Verwirrtheit) kennen und stets Traubenzucker mitführen.","Alkohol kann schwere und verzögerte Unterzuckerungen auslösen.","Unterzuckerungen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"gliclazid":{"wirkmechanismus":"Senkt den Blutzucker, indem es die Bauchspeicheldrüse zur vermehrten Ausschüttung von Insulin anregt. Gliclazid bindet an den Sulfonylharnstoff-Rezeptor (SUR1) der Betazellen und schliesst dort ATP-abhängige Kaliumkanäle; die Zellmembran wird depolarisiert, Calcium strömt ein und Insulin wird freigesetzt. Weil dies auch bei normalem Blutzucker geschieht, kann eine Unterzuckerung entstehen. Gliclazid wird in der Leber vor allem über CYP2C9 und CYP2C19 abgebaut; die Retardtablette wird einmal täglich zum Frühstück eingenommen.","nebenwirkungen":{"selten":["Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie, Granulozytopenie), meist nach Absetzen rückläufig"],"unbekannt":["Hypoglykämie (Unterzuckerung), teils lang anhaltend – die wichtigste Nebenwirkung","Magen-Darm-Beschwerden (Bauchschmerzen, Übelkeit, Erbrechen, Verdauungsbeschwerden, Durchfall, Verstopfung)","Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht, Angioödem)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, sehr selten DRESS)","Erhöhte Leberwerte, vereinzelt Hepatitis mit Gelbsucht","Vorübergehende Sehstörungen zu Behandlungsbeginn"]},"schwangerschaft":"Nicht anwenden: Bei geplanter oder eingetretener Schwangerschaft wird auf Insulin umgestellt.","stillzeit":"Kontraindiziert: Gefahr der Unterzuckerung beim gestillten Kind.","hinweise":["Einmal täglich zum Frühstück einnehmen; die Retardtablette nicht zerkauen (teilbare Tabletten nur an der Bruchrille teilen).","Keine Mahlzeit auslassen und Traubenzucker bei sich tragen; Unterzuckerungen können lange anhalten.","Alkohol meiden, da er Unterzuckerungen verstärkt.","Bei Fieber, schweren Infekten oder vor Operationen ärztlich klären, ob vorübergehend Insulin nötig ist."],"darreichung":["Tabletten mit veränderter Wirkstofffreisetzung (Retardtabletten)"]},"glimepirid":{"wirkmechanismus":"Senkt den Blutzucker, indem es die Bauchspeicheldrüse zur vermehrten Ausschüttung von Insulin anregt. Glimepirid bindet an den Sulfonylharnstoff-Rezeptor der Betazellen und schliesst ATP-abhängige Kaliumkanäle; die Membran wird depolarisiert, Calcium strömt ein und Insulin wird freigesetzt – auch bei normalem Blutzucker, daher die Gefahr von Unterzuckerungen. Daneben werden Wirkungen ausserhalb der Bauchspeicheldrüse beschrieben (bessere Insulinempfindlichkeit des Gewebes). Glimepirid wird in der Leber fast vollständig über CYP2C9 abgebaut und wirkt rund 24 Stunden, sodass eine Einnahme pro Tag genügt.","nebenwirkungen":{"selten":["Hypoglykämie (Unterzuckerung), teils lang anhaltend","Blutbildveränderungen: Thrombozytopenie, Leukopenie, Granulozytopenie, Agranulozytose, hämolytische Anämie, Panzytopenie"],"sehrSelten":["Magen-Darm-Beschwerden (Übelkeit, Erbrechen, Durchfall, Völlegefühl, Bauchschmerzen)","Leberfunktionsstörung mit Cholestase und Gelbsucht, Hepatitis bis Leberversagen","Leukozytoklastische Vaskulitis (Entzündung kleiner Blutgefässe)","Leichte Überempfindlichkeitsreaktionen, die sich zu schweren Reaktionen mit Atemnot, Blutdruckabfall und Schock entwickeln können","Hyponatriämie (Natriummangel im Blut)"],"unbekannt":["Hautreaktionen wie Juckreiz, Ausschlag, Nesselsucht","Photosensibilität (erhöhte Lichtempfindlichkeit der Haut)","Vorübergehende Sehstörungen, vor allem zu Behandlungsbeginn","Schwere Thrombozytopenie (Blutplättchen unter 10'000/µl) mit Blutungsneigung","Erhöhte Leberenzyme"]},"schwangerschaft":"Kontraindiziert: Bei geplanter oder eingetretener Schwangerschaft wird auf Insulin umgestellt.","stillzeit":"Kontraindiziert: Glimepirid geht in die Muttermilch über, Gefahr der Unterzuckerung beim Kind – auf Insulin umstellen oder abstillen.","hinweise":["Einmal täglich kurz vor oder während des Frühstücks bzw. der ersten Hauptmahlzeit unzerkaut mit Flüssigkeit einnehmen; danach keine Mahlzeit auslassen.","Immer Traubenzucker bei sich tragen; Unterzuckerungen können lange anhalten.","Alkohol meiden, da er die Wirkung unvorhersehbar verändert.","Blutbild und Leberwerte regelmässig kontrollieren lassen."],"darreichung":["Tabletten"]},"glofitamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit bösartigen B-Zellen, damit diese zerstört werden. Glofitamab ist ein bispezifischer Antikörper mit zwei Bindungsstellen für CD20 auf B-Zellen und einer für CD3 auf T-Zellen. Die so aktivierten T-Zellen vermehren sich, setzen Zytokine und zytotoxische Proteine frei und töten die CD20-tragenden Zellen. Eine einmalige Vorbehandlung mit Obinutuzumab eine Woche vorher vermindert die B-Zellen im Blut und senkt so das Risiko eines Zytokin-Freisetzungs-Syndroms.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Neutropenie, Anämie, Thrombozytopenie","Elektrolytstörungen (Phosphat, Magnesium oder Calcium zu tief)","Hautausschlag","Fieber","Kopfschmerzen","Durchfall, Verstopfung, Übelkeit"],"haeufig":["Infektionen inkl. Lungenentzündung und Sepsis (Blutvergiftung)","Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Tumor-Flare (schmerzhafte Lymphknotenschwellung)","ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom)","Erhöhte Leber- und Bilirubinwerte","Erbrechen"],"unbekannt":["Tumorlysesyndrom"]},"schwangerschaft":"Kann beim Ungeborenen die B-Zellen vermindern; in der Schwangerschaft nicht empfohlen. Frauen verhüten während und mindestens 2 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 2 Monate nach der letzten Dosis nicht stillen.","hinweise":["Eine Woche vor der ersten Dosis wird einmalig Obinutuzumab gegeben; nach der ersten Glofitamab-Dosis folgt eine Überwachung im Spital.","Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Infektzeichen umgehend ärztlich abklären lassen.","Patientenkarte immer mitführen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"glucagon":{"wirkmechanismus":"Hebt den Blutzucker rasch an, indem es die Leber veranlasst, gespeicherten Zucker freizusetzen. Glucagon bindet an Glucagon-Rezeptoren der Leberzellen und steigert über cAMP den Abbau von Glykogen (Glykogenolyse) sowie die Neubildung von Glukose (Glukoneogenese). Die Wirkung setzt nach etwa 10 Minuten ein; sie bleibt weitgehend aus, wenn die Glykogenspeicher der Leber leer sind, z. B. nach langem Fasten oder bei alkoholbedingter Unterzuckerung. Zusätzlich entspannt Glucagon die glatte Muskulatur des Magen-Darm-Trakts, was bei Untersuchungen genutzt wird.","nebenwirkungen":{"sehrHaeufig":["Übelkeit und Erbrechen (beim Nasenpulver sehr häufig; bei der Injektion Übelkeit häufig, Erbrechen gelegentlich)","Nasenpulver: Reizung von Nase und Atemwegen (Niesen, verstopfte oder laufende Nase, Husten, Nasenbluten)","Nasenpulver: tränende Augen","Nasenpulver: Kopfschmerzen"],"haeufig":["Nasenpulver: Geschmacksstörungen","Nasenpulver: gerötete oder juckende Augen","Nasenpulver: Juckreiz der Haut"],"selten":["Bauchschmerzen (Injektion)"],"sehrSelten":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Vorübergehender Anstieg von Puls und Blutdruck","Unterzuckerung nach diagnostischer Anwendung (nach dem anfänglichen Blutzuckeranstieg)"]},"schwangerschaft":"Erlaubt: Glucagon passiert die Plazenta nicht; eine schwere Unterzuckerung soll auch in der Schwangerschaft behandelt werden.","stillzeit":"Erlaubt: Glucagon wird aus dem Blut rasch abgebaut und im Verdauungstrakt des Säuglings zerstört.","hinweise":["Sobald die Person wieder wach ist und schlucken kann, Traubenzucker und danach eine kohlenhydrathaltige Mahlzeit geben, damit der Blutzucker nicht erneut absinkt.","Bewusstlose in die stabile Seitenlage bringen (Erbrechen möglich) und den Notruf 144 alarmieren, wenn nach 10–15 Minuten keine Besserung eintritt.","Angehörige sollten die Anwendung vorher üben und das Verfalldatum regelmässig prüfen; das Nasenpulver muss nicht aktiv eingeatmet werden.","Nach einer schweren Unterzuckerung die Ärztin oder den Arzt informieren – die Diabetesbehandlung muss eventuell angepasst werden."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (Fertigspritze)","Nasenpulver im Einzeldosisbehältnis"]},"glucose":{"wirkmechanismus":"Liefert dem Körper schnell verfügbare Energie und Flüssigkeit. Glucose ist der wichtigste Energieträger der Zellen; sie wird mit Hilfe von Insulin in die Zellen aufgenommen und zu Kohlendioxid und Wasser verstoffwechselt (rund 4 kcal pro Gramm) oder als Glykogen gespeichert. Eine 5 %-Lösung ist anfangs etwa blutisoton, nach dem Verbrauch der Glucose bleibt aber freies Wasser zurück – sie wirkt im Körper deshalb wie eine natriumfreie, hypotone Lösung. Konzentrierte Lösungen heben den Blutzucker rasch an.","nebenwirkungen":{"unbekannt":["Hyperglykämie (zu hoher Blutzucker), Zucker im Urin, vermehrtes Wasserlassen","Akute Hyponatriämie mit Hirnschwellung (hyponatriämische Enzephalopathie): Kopfschmerzen, Übelkeit, Krampfanfälle, Bewusstseinsstörung","Hypokaliämie, Hypophosphatämie, Hypomagnesiämie","Überwässerung, Ödeme","Venenreizung und Venenentzündung (Thrombophlebitis), v. a. bei konzentrierten Lösungen","Gewebeschäden bei Austritt neben die Vene (Paravasat)","Fieber, Schüttelfrost, Reaktionen an der Infusionsstelle","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Kann angewendet werden. Blutzucker, Natrium und Flüssigkeitshaushalt überwachen; bei der Geburt kann zu viel Glucose beim Neugeborenen eine Unterzuckerung und bei der Mutter einen Natriummangel auslösen.","stillzeit":"Kann angewendet werden.","hinweise":["Wird nur unter ärztlicher Kontrolle gegeben: Blutzucker, Elektrolyte (v. a. Natrium und Kalium) und Flüssigkeitsbilanz werden überwacht.","Lösungen über etwa 10 % reizen die Venen und werden in der Regel über einen zentralen Venenkatheter gegeben.","Nicht über dasselbe Infusionsbesteck wie Blutkonserven geben (Verklumpung roter Blutkörperchen).","Bei Alkoholkranken und Mangelernährten vorher Vitamin B1 (Thiamin) verabreichen."],"darreichung":["Infusionslösung 5 % und 10 %","Konzentrierte Lösungen (z. B. 20 %, 40 %, 50 %, 70 %)"]},"glycerol":{"wirkmechanismus":"Löst den Stuhlgang aus, indem es Wasser in den Enddarm zieht und die Schleimhaut leicht reizt. Glycerol wirkt osmotisch und weicht den Stuhl auf; zugleich dient es als Gleitmittel. Der Reiz auf die Enddarmschleimhaut und die Dehnung lösen den natürlichen Entleerungsreflex aus, in der Regel innerhalb von 15 bis 30 Minuten. Die Wirkung bleibt auf den Enddarm beschränkt.","nebenwirkungen":{"unbekannt":["Brennen, Reizung oder Missempfindungen im Enddarm","Leichte Bauchkrämpfe","Schleimhautreizung bis Entzündung des Enddarms (Proktitis) bei häufiger Anwendung","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Wirkt nur örtlich; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Zäpfchen bei Bedarf kurz mit Wasser anfeuchten und tief in den After einführen; die Wirkung tritt meist nach 15–30 Minuten ein.","Nicht über längere Zeit regelmässig anwenden; bei anhaltender Verstopfung ärztlich abklären lassen."],"darreichung":["Suppositorien (Zäpfchen) für Erwachsene und Kinder"]},"glycerolphenylbutyrat":{"wirkmechanismus":"Eröffnet dem Körper einen Ersatzweg zur Ausscheidung von Stickstoff, wenn der Harnstoffzyklus gestört ist. Glycerolphenylbutyrat besteht aus Glycerin und drei Phenylbutyrat-Molekülen; im Darm setzen Lipasen der Bauchspeicheldrüse Phenylbutyrat frei, das zu Phenylacetat umgewandelt wird. Phenylacetat bindet Glutamin zu Phenylacetylglutamin, das mit zwei Stickstoffatomen pro Molekül über die Niere ausgeschieden wird. Der Wirkstoff wird langsamer freigesetzt als Natriumphenylbutyrat und enthält kein Natrium.","nebenwirkungen":{"haeufig":["Durchfall, Blähungen","Übelkeit, Erbrechen, Bauchschmerzen","Kopfschmerzen, Schwindel","Appetitminderung","Müdigkeit","Unangenehmer Körpergeruch"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; während der Behandlung nicht stillen.","hinweise":["Mit den Mahlzeiten einnehmen, mit der beigelegten Dosierspritze direkt in den Mund oder über eine Ernährungssonde.","Eiweissarme Diät und allfällige Ergänzungen nach Anweisung des Stoffwechselzentrums weiterführen.","Benommenheit, Verwirrtheit, Kopfschmerzen oder Hörstörungen ärztlich melden; Ammoniak und Aminosäuren werden regelmässig kontrolliert."],"darreichung":["Flüssigkeit zum Einnehmen"]},"glyceroltrinitrat":{"wirkmechanismus":"Erweitert die Blutgefässe und entlastet so das Herz, das dadurch weniger Sauerstoff braucht. Glyceroltrinitrat setzt in der Gefässwand Stickstoffmonoxid (NO) frei, das die lösliche Guanylatcyclase aktiviert; das gebildete cGMP entspannt die glatte Gefässmuskulatur. Vor allem die Venen werden erweitert, wodurch weniger Blut zum Herzen zurückfliesst (Vorlastsenkung); in höheren Dosen weiten sich auch Arterien und Herzkranzgefässe. Am After entspannt es den inneren Schliessmuskel und verbessert die Durchblutung der Fissur. Bei Dauergebrauch ohne Pause lässt die Wirkung nach (Nitrattoleranz).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (Nitratkopfschmerz), besonders zu Beginn"],"haeufig":["Schwindel, Benommenheit, Schläfrigkeit","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Herzrasen (Reflextachykardie)","Schwächegefühl","Übelkeit","Hautreaktionen an der Pflasterstelle (Rötung, Juckreiz, Brennen); Juckreiz und Brennen am After (Salbe)"],"gelegentlich":["Kreislaufkollaps, teils mit Bradykardie und Ohnmacht (Synkope)","Paradoxe Verstärkung der Angina-pectoris-Beschwerden","Erbrechen","Gesichtsrötung (Flush)","Allergische Hautreaktionen"],"sehrSelten":["Methämoglobinämie (verminderter Sauerstofftransport im Blut) bei hohen Dosen","Exfoliative Dermatitis (schwere schuppende Hautentzündung)"],"unbekannt":["Nachlassende Wirkung bei Dauergebrauch (Nitrattoleranz)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; es gibt nur wenige Daten, ein Risiko für das Ungeborene ist bisher nicht bekannt.","stillzeit":"Nicht bekannt, ob Glyceroltrinitrat in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Beim Anfall hinsetzen (Kollapsgefahr) und Kapsel zerbeissen; wenn die Beschwerden nach 5 Minuten nicht nachlassen, eine weitere Dosis nehmen – hält der Brustschmerz trotzdem an, sofort Notruf 144 (möglicher Herzinfarkt).","Pflaster täglich wechseln und eine nitratfreie Pause von 8–12 Stunden (meist nachts) einhalten, damit die Wirkung erhalten bleibt.","Keine Potenzmittel (Sildenafil, Tadalafil usw.) gleichzeitig verwenden; Alkohol meiden.","Pflaster vor einer MRI-Untersuchung, Kardioversion oder Defibrillation entfernen."],"darreichung":["Zerbeisskapseln","Transdermales Pflaster","Infusionslösung","Rektalsalbe"]},"glycopyrronium":{"wirkmechanismus":"Entspannt die Muskulatur der Atemwege und erweitert so die Bronchien; zudem bremst es die Bildung von Speichel und Schleim. Glycopyrronium blockiert die Muskarinrezeptoren (v. a. M3) für den Botenstoff Acetylcholin an der glatten Bronchialmuskulatur und an Drüsen. Inhaliert setzt die Wirkung innert Minuten ein und hält etwa 24 Stunden an. Als quartäre Ammoniumverbindung gelangt es kaum ins Gehirn, deshalb fehlen zentrale Nebenwirkungen wie Verwirrtheit weitgehend; als Spritze hebt es zudem die pulsverlangsamende Wirkung des Vagusnervs auf das Herz auf.","nebenwirkungen":{"haeufig":["Mundtrockenheit","Nasen-Rachen-Entzündung (Nasopharyngitis)","Schlafstörungen","Kopfschmerzen","Magen-Darm-Infektion (Gastroenteritis)","Harnwegsinfekt"],"gelegentlich":["Vorhofflimmern, Herzklopfen (Palpitationen)","Harnverhalt, Schmerzen beim Wasserlösen","Überempfindlichkeitsreaktionen","Verstopfte Nasennebenhöhlen, Husten mit Auswurf, Rachenreizung, Nasenbluten","Hautausschlag, Juckreiz","Erhöhter Blutzucker (Hyperglykämie)","Zahnkaries, Verdauungsbeschwerden","Gliederschmerzen, Müdigkeit, Schwäche"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen oder Rachen)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Heiserkeit (Dysphonie)","Verschwommenes Sehen, Anstieg des Augeninnendrucks","Nach Injektion: Herzrasen (Tachykardie), Pupillenerweiterung, vermindertes Schwitzen"]},"schwangerschaft":"Erfahrungen fehlen weitgehend; nur anwenden, wenn der Nutzen das mögliche Risiko überwiegt.","stillzeit":"Nicht bekannt, ob Glycopyrronium in die Muttermilch übergeht; nur nach ärztlicher Nutzen-Risiko-Abwägung anwenden.","hinweise":["Kapseln nur zum Inhalieren mit dem Breezhaler-Gerät verwenden, nicht schlucken; täglich zur gleichen Zeit anwenden.","Nicht gegen akute Atemnot geeignet – dafür ein rasch wirksames Notfallspray bereithalten.","Bei plötzlicher Atemnot oder pfeifender Atmung direkt nach dem Inhalieren Anwendung abbrechen und sofort ärztliche Hilfe holen.","Mundtrockenheit fördert Karies: gute Mundhygiene und regelmässige Zahnkontrollen."],"darreichung":["Kapseln mit Inhalationspulver (Breezhaler)","Injektionslösung"]},"golimumab":{"wirkmechanismus":"Hemmt den Entzündungsbotenstoff TNF-alpha, der bei Rheuma und chronisch-entzündlichen Darmerkrankungen die Entzündung antreibt. Golimumab ist ein vollständig humaner monoklonaler IgG1-Antikörper, der lösliches und membrangebundenes TNF-alpha mit hoher Affinität bindet und so dessen Bindung an die TNF-Rezeptoren verhindert. Dadurch sinken Entzündungsmarker wie CRP und Interleukin-6, und die Gewebeschädigung wird gebremst. Wegen der langen Halbwertszeit genügt eine Injektion pro Monat.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (Nasen-Rachen-Entzündung, Schnupfen)"],"haeufig":["Bakterielle und virale Infektionen (z. B. Lungenentzündung, Grippe, Herpes, Bronchitis, Nebenhöhlenentzündung), oberflächliche Pilzinfektionen","Anämie (Blutarmut)","Allergische Reaktionen, Asthma-Beschwerden","Depression, Schlaflosigkeit","Schwindel, Kopfschmerzen, Missempfindungen, Bluthochdruck","Bauchschmerzen, Übelkeit, Verdauungsbeschwerden, Mundentzündung","Erhöhte Leberwerte, Haarausfall, Hautausschlag, Juckreiz","Fieber, Schwäche, Reaktionen an der Injektionsstelle"],"gelegentlich":["Sepsis und opportunistische Infektionen","Bösartige Tumoren, Hautkrebs (ausser Melanom)","Leukopenie, Thrombozytopenie, Panzytopenie","Schilddrüsenstörungen, erhöhter Blutzucker und Blutfette","Demyelinisierende Erkrankungen","Herzinsuffizienz, Herzrhythmusstörungen"],"selten":["Tuberkulose, Hepatitis-B-Reaktivierung","Lymphome, Leukämie, Melanom","Anaphylaxie (schwere allergische Reaktion)","Lupus-ähnliches Syndrom","Interstitielle Lungenerkrankung"],"unbekannt":["Hepatosplenisches T-Zell-Lymphom","Merkelzellkarzinom","Sarkoidose"]},"schwangerschaft":"Nur wenn eindeutig erforderlich; Frauen im gebärfähigen Alter sollen während und bis 6 Monate nach der letzten Dosis verhüten. Im Mutterleib exponierte Säuglinge bis 6 Monate nach der letzten Dosis in der Schwangerschaft nicht mit Lebendimpfstoffen impfen.","stillzeit":"Während und bis mindestens 6 Monate nach der Behandlung nicht stillen.","hinweise":["Einmal im Monat am gleichen Kalendertag spritzen.","Vor Beginn Tuberkulose- und Hepatitis-B-Test; Impfungen möglichst vorher auffrischen.","Fieber, anhaltender Husten oder andere Infektzeichen sofort ärztlich melden.","Im Kühlschrank lagern; bei Latexallergie ärztlich melden (Nadelschutzkappe enthält Latex)."],"darreichung":["Injektionslösung im Fertigpen oder in Fertigspritze (subkutan)"]},"goserelin":{"wirkmechanismus":"Schaltet über die Hirnanhangsdrüse die Bildung von Geschlechtshormonen ab. Goserelin ist ein synthetisches GnRH-Analogon, das aus einem kleinen Implantat gleichmässig freigesetzt wird. Nach einem kurzen anfänglichen Hormonanstieg führt die Dauerstimulation zur Desensibilisierung der Hypophyse: LH und FSH sinken, Testosteron bzw. Östradiol fallen nach etwa 3 Wochen auf Kastrationsniveau.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Vermehrtes Schwitzen","Libidoabnahme, Erektionsstörungen","Scheidentrockenheit, Veränderungen der Brustgrösse (bei Frauen)","Akne, fettige Haut (bei Frauen)"],"haeufig":["Kribbeln (Parästhesien)","Knochenschmerzen (vorübergehend zu Beginn)","Gynäkomastie (Brustvergrösserung beim Mann)","Gelenkschmerzen","Hautausschlag","Blutdruckveränderungen","Abnahme der Knochendichte","Reaktionen an der Injektionsstelle (Schmerzen, Bluterguss)","Stimmungsschwankungen, Depression","Herzinsuffizienz, Herzinfarkt (bei Männern)"],"gelegentlich":["Hyperkalzämie bei Brustkrebs mit Knochenmetastasen","Harnleiterverengung"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Eierstockzysten"],"sehrSelten":["Hypophysenapoplexie (Einblutung in einen Hypophysentumor)"],"unbekannt":["QT-Verlängerung","Interstitielle Lungenerkrankung","Haarausfall"]},"schwangerschaft":"Kontraindiziert. Vor Beginn Schwangerschaft ausschliessen; während der Behandlung nicht hormonell verhüten (z. B. Kondom, Spirale ohne Hormon).","stillzeit":"Kontraindiziert.","hinweise":["Termine für das Implantat genau einhalten (alle 4 bzw. 12 Wochen).","Bauchschmerzen, Schwellung oder Kreislaufbeschwerden nach der Injektion sofort melden (Blutung).","Bei Langzeitbehandlung Knochendichte und Blutzucker kontrollieren."],"darreichung":["Implantat in Fertigspritze"]},"granisetron":{"wirkmechanismus":"Verhindert Übelkeit und Erbrechen, indem es eine Wirkung des Botenstoffs Serotonin blockiert. Chemotherapie und Bestrahlung setzen im Darm Serotonin frei, das über 5-HT3-Rezeptoren an den Enden des Vagusnervs und im Brechzentrum des Hirnstamms (Area postrema) den Brechreflex auslöst. Granisetron blockiert diese 5-HT3-Rezeptoren hochselektiv; an Dopamin- oder Histaminrezeptoren wirkt es kaum.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Obstipation (Verstopfung)"],"haeufig":["Schlaflosigkeit","Durchfall","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Überempfindlichkeitsreaktionen bis Anaphylaxie, Nesselsucht","Hautausschlag","Extrapyramidale Störungen (unwillkürliche Bewegungen, Muskelverkrampfungen)","QT-Verlängerung im EKG"],"unbekannt":["Serotonin-Syndrom, vor allem zusammen mit anderen serotonergen Mitteln"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber nicht anwenden, ausser die Ärztin oder der Arzt hält es für eindeutig notwendig.","stillzeit":"Unbekannt, ob Granisetron in die Muttermilch übergeht; während der Behandlung wird vom Stillen abgeraten.","hinweise":["Bei mehreren Tagen ohne Stuhlgang, starken Bauchschmerzen oder aufgeblähtem Bauch ärztlichen Rat einholen.","Herzklopfen, Schwindel oder Ohnmacht sofort melden."],"darreichung":["Filmtabletten","Konzentrat zur Herstellung einer Injektions- oder Infusionslösung"]},"guaifenesin":{"wirkmechanismus":"Erleichtert das Abhusten, indem es den Bronchialschleim verflüssigt. Guaifenesin regt vermutlich über einen Reflex, der von der Magenschleimhaut ausgeht, die Bildung von dünnflüssigerem Bronchialsekret an und vermindert so dessen Zähigkeit. Dadurch wird der Schleim besser von den Flimmerhärchen und durch Husten aus den Atemwegen befördert.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen","Magen-Darm-Beschwerden, Bauchschmerzen, Durchfall","Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht)","Schwindel, Kopfschmerzen"]},"schwangerschaft":"Nur begrenzte Erfahrungen; im ersten Schwangerschaftsdrittel vorsichtshalber nicht anwenden, danach nur nach ärztlicher Rücksprache.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; nur nach ärztlicher Rücksprache anwenden.","hinweise":["Während der Behandlung reichlich trinken; das unterstützt die Schleimlösung.","Die letzte Einnahme möglichst nicht unmittelbar vor dem Schlafengehen, da das Abhusten in der Nacht zunehmen kann.","Ohne ärztlichen Rat nicht länger als eine Woche anwenden."],"darreichung":["Tropfen zum Einnehmen"]},"guanfacin":{"wirkmechanismus":"Verbessert Aufmerksamkeit und Impulskontrolle, ohne anregend zu wirken. Guanfacin stimuliert gezielt Alpha-2A-Rezeptoren im präfrontalen Kortex, dem für Planung und Steuerung des Verhaltens zuständigen Hirnbereich, und verstärkt dort die Signalübertragung zwischen Nervenzellen. Über dieselben Rezeptoren im Hirnstamm senkt es die Aktivität des sympathischen Nervensystems, was Blutdruck und Puls vermindert und müde machen kann. Guanfacin wird über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit (Somnolenz)","Kopfschmerzen","Müdigkeit, Erschöpfung","Bauchschmerzen"],"haeufig":["Depression, Angst, Stimmungsschwankungen, Reizbarkeit","Schlaflosigkeit, Albträume, Lethargie","Schwindel","Bradykardie (verlangsamter Herzschlag), Hypotonie, Blutdruckabfall beim Aufstehen","Übelkeit, Erbrechen, Durchfall, Verstopfung, Mundtrockenheit","Appetitminderung, Gewichtszunahme","Hautausschlag","Einnässen (Enuresis)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Unruhe, Halluzinationen","Krampfanfälle","Ohnmacht (Synkope)","AV-Block 1. Grades, Herzrasen, Sinusarrhythmie","Asthma","Erhöhte Leberwerte (ALT)","Brustschmerzen, Schwäche, Blässe"],"selten":["Bluthochdruck","Sinusknotensyndrom","Unwohlsein"],"unbekannt":["Verlängerte QT-Zeit im EKG"]},"schwangerschaft":"Nicht empfohlen; es liegen kaum Erfahrungen vor. Frauen im gebärfähigen Alter sollen während der Behandlung verhüten.","stillzeit":"Nicht bekannt, ob Guanfacin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nie abrupt absetzen – schrittweise reduzieren, sonst kann der Blutdruck stark ansteigen.","Einmal täglich einnehmen, Tablette ganz schlucken; nicht mit fettreichem Essen oder Grapefruitsaft.","Puls, Blutdruck, Grösse und Gewicht regelmässig ärztlich kontrollieren lassen.","Müdigkeit kann die Reaktionsfähigkeit beim Velofahren, Autofahren oder Sport beeinträchtigen."],"darreichung":["Retardtabletten"]},"guselkumab":{"wirkmechanismus":"Dämpft fehlgeleitete Entzündungsreaktionen in Haut, Gelenken und Darm. Guselkumab ist ein humaner monoklonaler IgG1-Antikörper, der die p19-Untereinheit des Botenstoffs Interleukin-23 bindet. Dadurch wird die IL-23-abhängige Aktivierung von Th17-Zellen und die Freisetzung entzündungsfördernder Botenstoffe wie IL-17 und IL-22 gehemmt.","nebenwirkungen":{"sehrHaeufig":["Atemwegsinfektionen"],"haeufig":["Kopfschmerzen","Gelenkschmerzen","Durchfall, Magen-Darm-Infekt (Gastroenteritis)","Reaktionen an der Einstichstelle","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Herpes-simplex-Infektionen","Pilzinfektionen der Haut (Tinea)","Überempfindlichkeitsreaktionen, Ausschlag, Nesselsucht","Verminderte Neutrophilenzahl"],"selten":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Vorsichtshalber während der Schwangerschaft vermeiden; Frauen im gebärfähigen Alter verhüten während und bis 12 Wochen nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist unbekannt; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Vor Beginn auf Tuberkulose testen und den Impfstatus vervollständigen lassen.","Bei Fieber, anhaltendem Husten oder Gelbsucht ärztlich abklären lassen.","Im Kühlschrank lagern, nicht schütteln."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen)","Konzentrat zur Herstellung einer Infusionslösung"]}});
